// nbinput.hpp - Non-blocking keyboard input for CLI programs (header-only, C++17)
// Generated by Claude
//
// Platforms : Linux, macOS, Windows (no external dependencies)
// Scope     : plain ASCII characters + arrow keys / Home / End / Delete
//
// Quick example:
//
//     nbi::Input in;                       // enable non-blocking mode (RAII)
//     while (running) {
//         int k = in.poll();               // returns immediately, never waits
//         if (k == 'q') break;
//         if (k == nbi::Key::Up) { ... }
//         update_game();
//     }                                    // terminal is restored automatically
//
#pragma once

#include <chrono>
#include <csignal>
#include <cstdlib>
#include <stdexcept>

#if defined(_WIN32)
  #ifndef NOMINMAX
    #define NOMINMAX
  #endif
  #ifndef WIN32_LEAN_AND_MEAN
    #define WIN32_LEAN_AND_MEAN
  #endif
  #include <conio.h>
  #include <windows.h>
#else
  #include <sys/select.h>
  #include <termios.h>
  #include <unistd.h>
#endif

namespace nbi {

// Value returned by poll()/wait() when there is no input.
inline constexpr int NONE = -1;

// Key codes. Plain ASCII characters are returned as-is ('a', '1', ' ', ...).
// Special keys use values >= 1000 so they never collide with ASCII.
namespace Key {
inline constexpr int Tab       = '\t';
inline constexpr int Enter     = '\n';   // Enter is always '\n' on every platform
inline constexpr int Escape    = 27;
inline constexpr int Backspace = 127;    // Backspace is always 127 on every platform
inline constexpr int Up        = 1000;
inline constexpr int Down      = 1001;
inline constexpr int Right     = 1002;
inline constexpr int Left      = 1003;
inline constexpr int Home      = 1004;
inline constexpr int End       = 1005;
inline constexpr int Delete    = 1006;
}  // namespace Key

// True for directly printable characters (space through '~').
inline constexpr bool is_printable(int k) { return k >= 32 && k <= 126; }

#if !defined(_WIN32)
namespace detail {

inline termios& saved_termios() { static termios t; return t; }
inline bool&    raw_active()    { static bool a = false; return a; }

inline void restore_terminal() noexcept {
    if (raw_active()) {
        tcsetattr(STDIN_FILENO, TCSANOW, &saved_termios());
        raw_active() = false;
    }
}

// Make sure the terminal is not left in a broken state when the program
// is stopped by Ctrl+C / kill: restore it, then re-raise with the default action.
inline void on_signal(int sig) {
    restore_terminal();
    std::signal(sig, SIG_DFL);
    std::raise(sig);
}

// Read one byte with a timeout (ms). timeout < 0 means wait forever.
// Returns NONE on timeout or error.
inline int read_byte(int timeout_ms) {
    fd_set fds;
    FD_ZERO(&fds);
    FD_SET(STDIN_FILENO, &fds);

    timeval tv{};
    timeval* ptv = nullptr;
    if (timeout_ms >= 0) {
        tv.tv_sec  = timeout_ms / 1000;
        tv.tv_usec = (timeout_ms % 1000) * 1000;
        ptv = &tv;
    }
    if (select(STDIN_FILENO + 1, &fds, nullptr, nullptr, ptv) <= 0) return NONE;

    unsigned char c;
    return read(STDIN_FILENO, &c, 1) == 1 ? c : NONE;
}

}  // namespace detail
#endif

// Enables non-blocking input for as long as this object is alive.
// The terminal is restored to its original state in the destructor.
// Only one instance may exist at a time.
class Input {
public:
    Input() {
        if (instance_alive()) throw std::logic_error("nbi::Input: only one instance is allowed");
#if !defined(_WIN32)
        using namespace detail;
        if (tcgetattr(STDIN_FILENO, &saved_termios()) != 0)
            throw std::runtime_error("nbi::Input: stdin is not a terminal (TTY)");

        termios raw = saved_termios();
        raw.c_lflag &= ~(ICANON | ECHO);   // no line buffering, no echo
        raw.c_cc[VMIN]  = 0;               // read() may return with 0 bytes...
        raw.c_cc[VTIME] = 0;               // ...and never waits
        tcsetattr(STDIN_FILENO, TCSANOW, &raw);
        raw_active() = true;

        std::atexit(restore_terminal);
        std::signal(SIGINT,  on_signal);
        std::signal(SIGTERM, on_signal);
        std::signal(SIGHUP,  on_signal);
#endif
        instance_alive() = true;
    }

    ~Input() {
#if !defined(_WIN32)
        detail::restore_terminal();
#endif
        instance_alive() = false;
    }

    Input(const Input&)            = delete;
    Input& operator=(const Input&) = delete;

    // Fetch one key if available; otherwise return NONE immediately.
    int poll() {
#if defined(_WIN32)
        if (!_kbhit()) return NONE;
        int c = _getch();
        if (c == 0 || c == 0xE0) {                 // special key (two-byte sequence)
            switch (_getch()) {
                case 72: return Key::Up;
                case 80: return Key::Down;
                case 77: return Key::Right;
                case 75: return Key::Left;
                case 71: return Key::Home;
                case 79: return Key::End;
                case 83: return Key::Delete;
                default: return NONE;
            }
        }
        if (c == '\r') return Key::Enter;
        if (c == 8)    return Key::Backspace;
        if (c == 3)    { std::raise(SIGINT); return NONE; }  // Ctrl+C, same as POSIX
        return c < 128 ? c : NONE;
#else
        int c = detail::read_byte(0);
        if (c == NONE) return NONE;
        if (c == Key::Escape) return parse_escape();
        if (c == '\r') return Key::Enter;
        if (c == 8)    return Key::Backspace;
        return c < 128 ? c : NONE;
#endif
    }

    // Wait up to timeout_ms for a key (-1 = no limit). Returns NONE on timeout.
    int wait(int timeout_ms = -1) {
        using clock = std::chrono::steady_clock;
        const auto deadline = clock::now() + std::chrono::milliseconds(timeout_ms);
        for (;;) {
#if defined(_WIN32)
            int k = poll();
            if (k != NONE) return k;
            if (timeout_ms >= 0 && clock::now() >= deadline) return NONE;
            Sleep(1);
#else
            int remaining = -1;
            if (timeout_ms >= 0) {
                auto left = std::chrono::duration_cast<std::chrono::milliseconds>(deadline - clock::now());
                if (left.count() <= 0) return poll();
                remaining = static_cast<int>(left.count());
            }
            fd_set fds;
            FD_ZERO(&fds);
            FD_SET(STDIN_FILENO, &fds);
            timeval tv{remaining / 1000, (remaining % 1000) * 1000};
            int r = select(STDIN_FILENO + 1, &fds, nullptr, nullptr, remaining >= 0 ? &tv : nullptr);
            if (r <= 0) return NONE;
            int k = poll();
            if (k != NONE) return k;   // unrecognized escape sequence: keep waiting
#endif
        }
    }

    // True if a key is waiting to be read (does not consume it).
    bool pressed() {
#if defined(_WIN32)
        return _kbhit() != 0;
#else
        fd_set fds;
        FD_ZERO(&fds);
        FD_SET(STDIN_FILENO, &fds);
        timeval tv{0, 0};
        return select(STDIN_FILENO + 1, &fds, nullptr, nullptr, &tv) > 0;
#endif
    }

    // Discard all pending input.
    void flush() { while (poll() != NONE) {} }

private:
    static bool& instance_alive() { static bool a = false; return a; }

#if !defined(_WIN32)
    // Called after receiving ESC. Distinguishes a real Esc key press
    // from escape sequences such as arrow keys.
    int parse_escape() {
        int c = detail::read_byte(20);             // escape sequences arrive almost instantly
        if (c == NONE) return Key::Escape;         // Esc pressed on its own
        if (c != '[' && c != 'O') return NONE;

        c = detail::read_byte(20);
        switch (c) {
            case 'A': return Key::Up;
            case 'B': return Key::Down;
            case 'C': return Key::Right;
            case 'D': return Key::Left;
            case 'H': return Key::Home;
            case 'F': return Key::End;
            case '1': case '7': return skip_tilde(Key::Home);
            case '4': case '8': return skip_tilde(Key::End);
            case '3':           return skip_tilde(Key::Delete);
            default: break;
        }
        // Unknown sequence: discard bytes up to the final byte (0x40-0x7E).
        while (c != NONE && !(c >= 0x40 && c <= 0x7E)) c = detail::read_byte(20);
        return NONE;
    }

    // Consume the trailing '~' of sequences like ESC [ 3 ~ (Delete).
    static int skip_tilde(int result) {
        int c = detail::read_byte(20);
        return c == '~' ? result : NONE;
    }
#endif
};

}  // namespace nbi